/**
 * Drift Detector (ADR-058)
 *
 * Tracks iteration history and detects four drift types that can degrade
 * swarm completion: stall, cycling, thrashing, and decay.  Pure TypeScript
 * with zero external dependencies.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface DriftConfig {
  stallThreshold: number;
  cyclingThreshold: number;
  thrashingThreshold: number;
  windowSize: number;
}

export type DriftType = 'stall' | 'cycling' | 'thrashing' | 'decay';
export type DriftSeverity = 'low' | 'medium' | 'high';
export type MitigationAction = 'escalate' | 'reprioritize' | 'reassign' | 'skip';

export interface DriftSignal {
  type: DriftType;
  severity: DriftSeverity;
  message: string;
  affectedTaskIds?: string[];
  detectedAt: number;
}

export interface MitigationStrategy {
  action: MitigationAction;
  taskIds: string[];
  reason: string;
}

export interface DriftMetrics {
  totalSignals: number;
  signalsByType: Record<DriftType, number>;
  iterationsSinceLastCompletion: number;
  completionRateHistory: number[];
  activeSignals: DriftSignal[];
}

// ---------------------------------------------------------------------------
// Defaults
// ---------------------------------------------------------------------------

const DEFAULT_DRIFT_CONFIG: DriftConfig = {
  stallThreshold: 5,
  cyclingThreshold: 3,
  thrashingThreshold: 3,
  windowSize: 10,
};

// ---------------------------------------------------------------------------
// DriftDetector
// ---------------------------------------------------------------------------

export class DriftDetector {
  private config: DriftConfig;

  private completionCounts: number[] = [];
  private taskFailures: Map<string, number> = new Map();
  private reassignments: Map<string, number> = new Map();
  private lastCompletedCount = 0;
  private iterationsSinceLastCompletion = 0;
  private signals: DriftSignal[] = [];
  private signalCounts: Record<DriftType, number> = {
    stall: 0,
    cycling: 0,
    thrashing: 0,
    decay: 0,
  };

  constructor(config: Partial<DriftConfig> = {}) {
    this.config = { ...DEFAULT_DRIFT_CONFIG, ...config };
  }

  // -----------------------------------------------------------------------
  // Recording methods — called by coordinator on each tick / event
  // -----------------------------------------------------------------------

  /**
   * Record an iteration snapshot.  The coordinator passes the current number
   * of completed tasks so we can track progress over time.
   */
  recordIteration(state: { completed: number }): void {
    this.completionCounts.push(state.completed);

    // Trim to sliding window — shift is O(1) amortised vs slice which copies
    while (this.completionCounts.length > this.config.windowSize) {
      this.completionCounts.shift();
    }

    if (state.completed > this.lastCompletedCount) {
      this.iterationsSinceLastCompletion = 0;
      this.lastCompletedCount = state.completed;
    } else {
      this.iterationsSinceLastCompletion++;
    }
  }

  /**
   * Record a task failure event.
   */
  recordTaskFailure(taskId: string, _reason?: string): void {
    const current = this.taskFailures.get(taskId) ?? 0;
    this.taskFailures.set(taskId, current + 1);
  }

  /**
   * Record an agent reassignment for a task.
   */
  recordAgentReassignment(taskId: string, _fromAgent: string, _toAgent: string): void {
    const current = this.reassignments.get(taskId) ?? 0;
    this.reassignments.set(taskId, current + 1);
  }

  // -----------------------------------------------------------------------
  // Detection — single call returns all active signals
  // -----------------------------------------------------------------------

  /**
   * Run all four drift detections and return any signals found.
   */
  detectDrift(): DriftSignal[] {
    this.signals = [];
    const now = Date.now();

    // 1. Stall detection
    if (this.iterationsSinceLastCompletion >= this.config.stallThreshold) {
      const signal: DriftSignal = {
        type: 'stall',
        severity: 'high',
        message: `No completions in ${this.iterationsSinceLastCompletion} iterations`,
        detectedAt: now,
      };
      this.signals.push(signal);
    }

    // 2. Cycling detection
    for (const [id, count] of this.taskFailures) {
      if (count >= this.config.cyclingThreshold) {
        const signal: DriftSignal = {
          type: 'cycling',
          severity: 'medium',
          message: `Task ${id} has failed ${count} times`,
          affectedTaskIds: [id],
          detectedAt: now,
        };
        this.signals.push(signal);
      }
    }

    // 3. Thrashing detection
    for (const [id, count] of this.reassignments) {
      if (count >= this.config.thrashingThreshold) {
        const signal: DriftSignal = {
          type: 'thrashing',
          severity: 'medium',
          message: `Task ${id} reassigned ${count} times`,
          affectedTaskIds: [id],
          detectedAt: now,
        };
        this.signals.push(signal);
      }
    }

    // 4. Decay detection — inline sums to avoid allocating temp arrays
    if (this.completionCounts.length >= this.config.windowSize) {
      const half = Math.floor(this.config.windowSize / 2);
      let firstSum = 0;
      let secondSum = 0;
      for (let i = 0; i < half; i++) firstSum += this.completionCounts[i];
      for (let i = half; i < this.completionCounts.length; i++) secondSum += this.completionCounts[i];

      if (firstSum > 0 && secondSum < firstSum * 0.5) {
        const signal: DriftSignal = {
          type: 'decay',
          severity: 'low',
          message: 'Completion rate declining',
          detectedAt: now,
        };
        this.signals.push(signal);
      }
    }

    // Increment signal counts
    for (const signal of this.signals) {
      this.signalCounts[signal.type]++;
    }

    return this.signals;
  }

  // -----------------------------------------------------------------------
  // Mitigation
  // -----------------------------------------------------------------------

  /**
   * Suggest a mitigation strategy for a given drift signal.
   */
  suggestMitigation(signal: DriftSignal): MitigationStrategy {
    const taskIds = signal.affectedTaskIds ?? [];

    switch (signal.type) {
      case 'stall':
        return {
          action: 'escalate',
          taskIds,
          reason: 'Swarm stalled - escalating remaining tasks',
        };
      case 'cycling':
        return {
          action: 'reprioritize',
          taskIds,
          reason: 'Task cycling detected - resetting to pending',
        };
      case 'thrashing':
        return {
          action: 'reassign',
          taskIds,
          reason: 'Agent thrashing detected - clearing owner',
        };
      case 'decay':
        return {
          action: 'skip',
          taskIds,
          reason: 'Completion rate decaying - consider skipping blocked tasks',
        };
    }
  }

  // -----------------------------------------------------------------------
  // State
  // -----------------------------------------------------------------------

  /**
   * Return current drift metrics.
   */
  getMetrics(): DriftMetrics {
    const totalSignals = Object.values(this.signalCounts).reduce((a, b) => a + b, 0);
    return {
      totalSignals,
      signalsByType: { ...this.signalCounts },
      iterationsSinceLastCompletion: this.iterationsSinceLastCompletion,
      completionRateHistory: [...this.completionCounts],
      activeSignals: [...this.signals],
    };
  }

  /**
   * Reset all internal state.
   */
  reset(): void {
    this.completionCounts = [];
    this.taskFailures.clear();
    this.reassignments.clear();
    this.lastCompletedCount = 0;
    this.iterationsSinceLastCompletion = 0;
    this.signals = [];
    this.signalCounts = { stall: 0, cycling: 0, thrashing: 0, decay: 0 };
  }

  /**
   * Return a copy of the current config.
   */
  getConfig(): DriftConfig {
    return { ...this.config };
  }

  /**
   * Merge partial config into the current config.
   */
  setConfig(config: Partial<DriftConfig>): void {
    this.config = { ...this.config, ...config };
  }
}
